      { \dim_set_eq:NN \l_tikzfill_gea_ystep_dim \l_tikzfill_gea_xstep_dim }
      { \dim_set:Nn \l_tikzfill_gea_ystep_dim { \fp_to_dim:n { \l_tikzfill_gea_xstep_dim * sqrt(3)/2 } } },
