    xflip~even/.default = true,

    xflip~odd/.is~choice,
    xflip~odd/true/.code  = \bool_set_true:N \l__tikzfill_gea_xflip_odd_bool,
    xflip~odd/false/.code = \bool_set_false:N \l__tikzfill_gea_xflip_odd_bool,
    xflip~odd/.default = true,

    xflip/.is~choice,
    xflip/true/.style  = { xflip~even=true,  xflip~odd=true },
